"""
Demo 2 -- The divisibility engine  f(a) | f(a + k f(a)).
Numerically confirms the identity that powers both main theorems.
"""
from typing import Callable, List


def poly(coeffs: List[int]) -> Callable[[int], int]:
    def f(x: int) -> int:
        acc = 0
        for c in reversed(coeffs):
            acc = acc * x + c
        return acc
    return f


def check_engine(f: Callable[[int], int], a: int, ks: range) -> bool:
    fa = f(a)
    return all((fa == 0) or (f(a + k * fa) % fa == 0) for k in ks)


if __name__ == "__main__":
    tests = {
        "n^2+n+41": poly([41, 1, 1]),
        "3n^3-2n+7": poly([7, -2, 0, 3]),
        "n^4+n+1": poly([1, 1, 0, 0, 1]),
    }
    for name, f in tests.items():
        for a in (0, 1, 2, 5):
            ok = check_engine(f, a, range(-30, 31))
            print(f"{name:12s} a={a:2d}: f(a)={f(a):6d} divides all f(a+k f(a))? {ok}")

"""
Demo 3 -- Certified failures and vanishing prime density.
For each candidate polynomial, constructs a composite value from a prime value
via the divisibility engine, then tracks the prime-output density as N grows.
"""
from typing import Callable, List, Optional, Tuple


def is_prime(n: int) -> bool:
    m = abs(n)
    if m < 2:
        return False
    d = 2
    while d * d <= m:
        if m % d == 0:
            return False
        d += 1
    return True


def poly(coeffs: List[int]) -> Callable[[int], int]:
    def f(x: int) -> int:
        acc = 0
        for c in reversed(coeffs):
            acc = acc * x + c
        return acc
    return f


def certified_failure(f: Callable[[int], int]) -> Optional[Tuple[int, int, int]]:
    for a in range(0, 500):
        p = f(a)
        if not is_prime(p):
            continue
        k = 1
        while k < 10000:
            n = a + k * p
            val = f(n)
            if abs(val) > abs(p) and val % p == 0:
                return (n, p, val)
            k += 1
    return None


def density(f: Callable[[int], int], N: int) -> float:
    return sum(1 for n in range(N + 1) if is_prime(f(n))) / (N + 1)


if __name__ == "__main__":
    fam = {"n^2+n+41": poly([41, 1, 1]), "n^2+n+17": poly([17, 1, 1])}
    for name, f in fam.items():
        cf = certified_failure(f)
        if cf:
            n, p, val = cf
            print(f"{name}: f({n})={val} = {p} x {val // p}  (composite)")
        dens = [f"N={N}:{density(f, N):.3f}" for N in (100, 1000, 5000)]
        print("   density:", "  ".join(dens))

