    if m < 2:
        return False
    d = 2
    while d * d <= m:
        if m % d == 0:
            return False
        d += 1
    return True


def prime_run_length(f: Callable[[int], int], start: int = 0,
                     cap: int = 10_000) -> int:
    """Length of the maximal run of consecutive prime outputs from `start`.
    Terminates for any nonconstant f by the impossibility theorem; `cap`
    is a defensive bound."""
    n = start
    while n - start < cap and is_prime(f(n)):
        n += 1
    return n - start

